/* Agent Team ドキュメントサイト 共通スタイル */

:root {
  --bg: #f7f8fa;
  --surface: #ffffff;
  --text: #1d2430;
  --muted: #5a6472;
  --accent: #2f5d9e;
  --border: #dfe3ea;
  --code-bg: #eef1f6;
}

* {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: "Hiragino Kaku Gothic ProN", "Yu Gothic", "Noto Sans JP", "Helvetica Neue", Arial, sans-serif;
  line-height: 1.85;
  font-size: 16px;
}

.wrap {
  max-width: 820px;
  margin: 0 auto;
  padding: 0 20px 64px;
}

/* ヘッダーとナビゲーション */

.site-header {
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  padding: 24px 0 18px;
  margin-bottom: 32px;
}

.site-title {
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--accent);
  margin: 0 0 10px;
}

.site-nav ul {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 8px 18px;
  margin: 0;
  padding: 0;
}

.site-nav a {
  color: var(--muted);
  text-decoration: none;
  font-size: 0.92rem;
  border-bottom: 1px solid transparent;
  padding-bottom: 2px;
}

.site-nav a:hover,
.site-nav a:focus {
  color: var(--accent);
  border-bottom-color: var(--accent);
}

