h1 {
  font-size: 1.7rem;
  line-height: 1.5;
  margin: 0 0 8px;
}

h2 {
  font-size: 1.22rem;
  margin: 40px 0 12px;
  padding-bottom: 8px;
  border-bottom: 2px solid var(--border);
}

h3 {
  font-size: 1.02rem;
  margin: 26px 0 8px;
}

.lead {
  color: var(--muted);
  font-size: 1.02rem;
  margin: 0 0 8px;
}

